function useFetch(url) {
  const [dados, setDados] = useState(null)
  const [carregando, setCarregando] = useState(true)
  useEffect(() => {
    fetch(url).then(r => r.json()).then(setDados).finally(() => setCarregando(false))
  }, [url])
  return { dados, carregando }
}

